import json,re,os
os.makedirs('/workspace/products/services/csv-text-diagnostic/worked-example',exist_ok=True)
out=[]
for p in ['products/research/manager-forum-csv-import-search.json','products/research/manager-forum-import-search.json']:
  t=open('/workspace/'+p,encoding='utf-8').read()
  try:
    d=json.loads(t)
  except Exception as e:
    print(p,'notjson',e); continue
  def walk(o):
    if isinstance(o,dict):
      yield o
      for v in o.values(): yield from walk(v)
    elif isinstance(o,list):
      for v in o: yield from walk(v)
    elif isinstance(o,str) and o.strip().startswith('{'):
      try: yield from walk(json.loads(o))
      except Exception: pass
  topics={}
  for o in walk(d):
    if 'topic_id' in o and 'blurb' in o: out.append({'src':p,'topic_id':o['topic_id'],'created_at':o.get('created_at'),'blurb':o['blurb']})
    if 'slug' in o and 'id' in o: topics[o['id']]=o.get('slug')
  for r in out:
    if r['src']==p: r['url']='https://forum.manager.io/t/%s/%s'%(topics.get(r['topic_id'],''),r['topic_id'])
kw=re.compile(r'(?i)(quot|comma|column|delimit|header|semicolon|\btabs?\b|line break|newline|paste|csv)')
hits=[r for r in out if kw.search(r['blurb'])]
json.dump({'total_posts':len(out),'hits':hits},open('/workspace/products/services/csv-text-diagnostic/worked-example/source-scan.json','w'),indent=1,ensure_ascii=False)
print(len(out),len(hits))
for r in hits: print(r['topic_id'],r['created_at'][:10],r['blurb'][:230].replace('\n',' '))
